/* Slide-based Binary Explorer. All pupil work stays in this browser. */
'use strict';
(() => {
const L=window.BINARY_LESSON,slides=L.slides,weights=[8,4,2,1];
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stops=[[14,88],[29,65],[42,49],[60,35],[43,22],[50,17],[52,11]];
let state=null,storageKey='',toastTimer;
const current=()=>slides[state.p];
const tr=(en,cn)=>en+(state?.lang==='zh'&&cn?`<span class="zh" lang="zh-Hans">${esc(cn)}</span>`:'');
const bits=n=>n.toString(2).padStart(4,'0');
const sum=s=>[...s].reduce((n,b,i)=>n+Number(b)*weights[i],0);
function hash(t){let h=2166136261;for(const c of t){h^=c.charCodeAt(0);h=Math.imul(h,16777619);}return(h>>>0).toString(36);}
function key(name,cls){return 'binary-explorer:'+(name.trim().toLowerCase()==='teacher'?'teacher':hash(name.trim().toLowerCase()+'|'+cls.trim().toLowerCase()));}
function freshGame(){return {climb:1,index:0,height:0,charged:false,bits:[0,0,0,0],answer:'',feedback:null,hint:false,attempts:[],completed:0};}
function fresh(identity,lang='en',color='teal'){return {version:2,lesson:L.id,slideOrder:slides.map(s=>s.id),identity,lang,color,p:0,furthest:0,records:{},done:[],history:[],game:freshGame(),demo:{tile:0},created:new Date().toISOString(),updated:new Date().toISOString()};}
const teacher=()=>state.identity.name.trim().toLowerCase()==='teacher';
function record(id=current().id){return state.records[id]||(state.records[id]={answer:'',check:null,hint:false,marks:[]});}
function log(type,value){state.history.push({at:new Date().toISOString(),slide:current().id,type,value});if(state.history.length>2000)state.history=state.history.slice(-2000);}
function save(){if(!state)return;state.updated=new Date().toISOString();try{localStorage.setItem(storageKey,JSON.stringify(state));$('.save-status')?.replaceChildren(document.createTextNode('Saved on this device'));}catch{$('.save-status')?.replaceChildren(document.createTextNode('Storage unavailable — use Backup'));}}
function toast(t){$('#toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',5500);}
function valid(s){
 const obj=x=>x!==null&&typeof x==='object'&&!Array.isArray(x);
 if(!obj(s)||s.version!==2||s.lesson!==L.id||!obj(s.identity)||typeof s.identity.name!=='string'||!s.identity.name.trim()||s.identity.name.length>80||typeof s.identity.cls!=='string'||s.identity.cls.length>30)return false;
 if(!Number.isInteger(s.p)||s.p<0||s.p>=slides.length||!Number.isInteger(s.furthest)||s.furthest<s.p||s.furthest>=slides.length)return false;
 if(!obj(s.records)||!Array.isArray(s.done)||!s.done.every(id=>slides.some(p=>p.id===id))||!Array.isArray(s.history)||!['en','zh'].includes(s.lang)||!['teal','coral','gold','rainbow'].includes(s.color))return false;
 for(const[id,r]of Object.entries(s.records)){if(!slides.some(p=>p.id===id)||!obj(r)||typeof r.answer!=='string'||r.answer.length>5000||typeof r.hint!=='boolean'||!Array.isArray(r.marks)||!r.marks.every(i=>Number.isInteger(i)&&i>=0&&i<8))return false;if(r.check&&(!obj(r.check)||![true,false,null].includes(r.check.correct)||typeof r.check.message!=='string'))return false;}
 if(s.demo&&(!obj(s.demo)||![0,1].includes(s.demo.tile)))return false;
 const g=s.game;return obj(g)&&Number.isInteger(g.index)&&g.index>=0&&g.index<=6&&g.index===g.height&&Number.isInteger(g.climb)&&g.climb>=1&&Array.isArray(g.bits)&&g.bits.length===4&&g.bits.every(n=>n===0||n===1)&&typeof g.answer==='string'&&typeof g.hint==='boolean'&&typeof g.charged==='boolean'&&Array.isArray(g.attempts)&&Number.isInteger(g.completed)&&g.completed>=0&&(!g.feedback||(obj(g.feedback)&&typeof g.feedback.message==='string'&&typeof g.feedback.correct==='boolean'));
}
function migrate(old){
 if(!old||old.version!==1||old.lesson!==L.id||!old.identity||typeof old.identity.name!=='string'||typeof old.identity.cls!=='string'||!old.answers)return null;
 const s=fresh(old.identity,old.lang||'en',old.color||'teal');
 const map={'starter-pattern':['starter-number','double3'],'starter-add':['starter-number','sum6'],'starter-cell':['starter-sheet','cell'],'type-knowledge':['types','know'],'type-skills':['types','skill'],'type-understanding':['types','understand'],'task1-data':['data','words'],'vote-chess':['votes','chess'],'vote-football':['votes','football'],'vote-drawing':['votes','drawing'],'vote-reading':['votes','reading'],'task1-information':['votes','winner'],'bit':['bit','bitvalues'],'byte':['byte','bytecount'],'four-bits':['byte','fourbyte'],'guided':['guided','bits'],'make3':['practice','make3'],'make9':['practice','make9'],'read10':['practice','read10'],'pit-phase':['pitstop','phase'],'pit-next':['pitstop','nextstep'],'exit-info':['plenary','info'],'exit-binary':['plenary','six'],'exit-byte':['plenary','byte']};
 const oldConfidence=['I can do this on my own','I can do this with an example','I need help to start','I have not tried this yet'];
 const aliases={'task1-data':{'Yes — they are recorded choices':'yes','No — data must be numbers':'no'},bit:{'0 or 1':'01','1 or 8':'18','Any number':'any'},'four-bits':{'No — a byte needs eight bits':'no',Yes:'yes'},'exit-info':{'Chess received the most votes: four out of eight.':'meaning','4':'number'},'exit-byte':{'8 bits':'8','4 bits':'4','1 bit':'1'}};
 for(const[id,[page,field]]of Object.entries(map)){let a=old.answers[page]?.[field];if(a===undefined||a===null||a==='')continue;a=Array.isArray(a)?a.join(''):String(a);const slide=slides.find(p=>p.id===id);if(slide.kind==='confidence')a=L.confidence[oldConfidence.indexOf(a)]?.[0]||'untried';a=aliases[id]?.[a]||a;if(a.toLowerCase().includes('not learned'))a='not-yet';if(slide.kind==='reflection'){const ix=['Use the example and practise another number','Explain the column values','Try zero or the biggest four-bit number','Ask my teacher to work through one example'].indexOf(a);a=['example','explain','challenge','teacher'][ix]||'example';}const r={answer:a,check:null,hint:false,marks:[]};if(old.checks?.[page]||['confidence','phase','reflection'].includes(slide.kind)){r.check=evaluate(slide,a);if(old.done?.includes(page))s.done.push(id);}s.records[id]=r;}
 const oldIDs=['welcome','starter-number','starter-sheet','types','data','information','votes','bit','byte','positions','example','guided','practice','summit','pitstop','plenary','finish'];
 const start={welcome:'welcome','starter-number':'starter-pattern','starter-sheet':'starter-cell',types:'type-knowledge',data:'task1-data',information:'task1-data',votes:'vote-chess',bit:'bit',byte:'byte',positions:'positions',example:'example',guided:'guided',practice:'make3',summit:'summit',pitstop:'pit-phase',plenary:'exit-info',finish:'finish'};
 s.p=Math.max(0,slides.findIndex(p=>p.id===start[oldIDs[old.p]]));s.furthest=Math.max(s.p,slides.findIndex(p=>p.id===start[oldIDs[old.furthest]]));s.game=old.game||freshGame();s.legacy=old;s.created=old.created||s.created;return valid(s)?s:null;
}
// Numeric slide positions must follow their original IDs when new practice is inserted.
function normaliseSaved(raw){
 if(!valid(raw))return null;
 const original=['welcome','starter-pattern','starter-add','starter-cell','type-knowledge','type-skills','type-understanding','task1-data','vote-chess','vote-football','vote-drawing','vote-reading','task1-information','task1-labels','bit','byte','four-bits','positions','count-rule','example','guided','make3','make9','read10','summit','pit-phase','pit-next','exit-info','exit-binary','exit-byte','finish'];
 const order=raw.slideOrder||original;
 if(!Array.isArray(order)||!order.length||order.length>500||new Set(order).size!==order.length||!order.every(id=>slides.some(s=>s.id===id))||raw.p>=order.length||raw.furthest>=order.length)return null;
 const next=structuredClone(raw);next.p=slides.findIndex(s=>s.id===order[raw.p]);next.furthest=Math.max(next.p,slides.findIndex(s=>s.id===order[raw.furthest]));next.slideOrder=slides.map(s=>s.id);
 return valid(next)?next:null;
}
function load(identity,lang,color){storageKey=key(identity.name,identity.cls);let old;try{old=JSON.parse(localStorage.getItem(storageKey));}catch{}const upgraded=migrate(old);state=normaliseSaved(old)||upgraded||fresh(identity,lang,color);state.identity=identity;state.lang=lang;state.color=color;if(!state.demo)state.demo={tile:0};save();render();if(upgraded)toast('Earlier work was kept and moved into the new slides. The original is preserved in your backup too.');}
function landing(){
 state=null;
 $('#app').innerHTML=`<header class="entry-header"><strong>01 · Binary Explorer</strong><span>Year 7 · 60 minutes · Independent learning</span></header><main id="main" class="entry"><div class="entry-art"><img src="assets/explorer-welcome.png" alt="A friendly robot explorer at a bright mountain base camp."><span class="entry-badge">Small bits. Big discoveries.</span></div><div class="entry-copy"><p class="eyebrow">Data · Information · Four-bit binary</p><h1>Your next discovery starts here.</h1><p>Organise eight activity votes. Explore <strong>8 · 4 · 2 · 1</strong>. Power your explorer’s climb.</p><form id="entry-form"><div class="entry-fields"><label>Your name<input name="name" required maxlength="80" autocomplete="off" placeholder="Your full name"></label><label>Class<input name="cls" required maxlength="30" autocomplete="off" placeholder="For example, Y7T"></label></div><label>Language support / 语言支持<select name="lang"><option value="en">English</option><option value="zh">English + 中文</option></select></label><fieldset class="colour-picker"><legend>Choose your explorer trail</legend>${['teal','coral','gold','rainbow'].map((c,i)=>`<button type="button" data-colour="${c}" aria-pressed="${i===0}"><span class="swatch ${c}" aria-hidden="true"></span>${c[0].toUpperCase()+c.slice(1)}</button>`).join('')}<input name="color" value="teal" type="hidden"></fieldset><button class="primary start" type="submit">Start or resume my lesson →</button></form><p class="entry-note">Work saves in this browser, not to a teacher database. Keep a backup before changing device.</p><button class="text-button" data-restore>Restore my JSON backup</button><div class="entry-error" role="status"></div></div></main><input id="restore-file" type="file" accept=".json,application/json" hidden>`;
 $('.entry-copy > p:nth-of-type(2)').innerHTML='Organise votes, lost property and lunch orders. Explore <strong>8 · 4 · 2 · 1</strong>. Power your explorer’s climb.';
 const form=$('#entry-form'),f=form.elements;let langChanged=false,colorChanged=false;
 f.lang.onchange=()=>langChanged=true;
 $$('[data-colour]').forEach(b=>b.onclick=()=>{colorChanged=true;f.color.value=b.dataset.colour;$$('[data-colour]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));});
 const prefs=()=>{f.cls.required=f.name.value.trim().toLowerCase()!=='teacher';try{const saved=JSON.parse(localStorage.getItem(key(f.name.value,f.cls.value)));if(valid(saved)||migrate(saved)){if(!langChanged)f.lang.value=saved.lang;if(!colorChanged){f.color.value=saved.color;$$('[data-colour]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.colour===saved.color)));}}}catch{}};
 f.name.oninput=prefs;f.cls.oninput=prefs;
 form.onsubmit=e=>{e.preventDefault();const identity={name:f.name.value.trim(),cls:f.cls.value.trim()};if(!identity.name||(!identity.cls&&identity.name.toLowerCase()!=='teacher')){$('.entry-error').textContent='Enter your name and class.';return;}load(identity,f.lang.value,f.color.value);};
 $('[data-restore]').onclick=()=>$('#restore-file').click();$('#restore-file').onchange=e=>restore(e.target.files[0]);
}
function image(name,alt){return `<img class="lesson-image" src="assets/${name}.png" alt="${esc(alt)}">`;}
function answerBits(s){const clean=record().answer.replace(/\s/g,'');return /^[01]{4}$/.test(clean)?clean:(s.initial||'0000');}
function board(digits,interactive=false,{live=false,game=false}={}){return `<div class="binary-visual"><p class="visual-caption">${tr('Fixed column values','固定位值')}</p><div class="binary-cards">${weights.map((w,i)=>`<${interactive?'button':'div'} class="binary-card ${digits[i]==='1'?'on':''}" ${interactive?`data-bit="${i}" data-game="${game}" aria-label="Value ${w}, digit ${digits[i]}. Tap to switch." aria-pressed="${digits[i]==='1'}"`:''}><span class="weight">${w}</span><span class="dots" aria-hidden="true">${'<i></i>'.repeat(w)}</span><span class="digit">${digits[i]}</span><span class="count-label">${digits[i]==='1'?'COUNT':'DO NOT COUNT'}</span></${interactive?'button':'div'}>`).join('')}</div>${live?`<p class="sum-line">${[...digits].map((b,i)=>b==='1'?weights[i]:null).filter(n=>n!==null).join(' + ')||'No values counted'} = ${sum(digits)}</p>`:''}<p class="visual-caption">${tr('1 = count its value · 0 = do not count it','1：计入这列的数值 · 0：不计入')}</p></div>`;}
function boxes(d){return `<div class="digit-boxes" aria-label="${d.length} bits: ${[...d].join(' ')}">${[...d].map(x=>`<span>${x}</span>`).join('')}</div>`;}
function voteTemplate(s){const active=s.kind==='vote'?s.activity:null,marks=record().marks;return `<div class="vote-template"><div class="template-heading"><strong>My vote investigation</strong><span>Eight fictional votes</span></div><div class="vote-slips" aria-label="All eight voting slips">${L.votes.map((v,i)=>`<button data-slip="${i}" aria-pressed="${marks.includes(i)}" class="slip ${marks.includes(i)?'marked':''}" aria-label="Vote ${i+1}: ${v}${marks.includes(i)?', marked as counted':''}"><span aria-hidden="true">${{Chess:'♟',Football:'⚽',Drawing:'✎',Reading:'▤'}[v]}</span>${v}</button>`).join('')}</div><table class="vote-table"><caption>Results table — your entries</caption><thead><tr><th scope="col">Activity</th><th scope="col">Number of votes</th></tr></thead><tbody>${L.activities.map(activity=>{const id='vote-'+activity.toLowerCase(),entry=state.records[id],value=entry?.answer||'',review=entry?.check?.correct===false;return `<tr class="${active===activity?'current-row':''}"><th scope="row">${activity}${active===activity?'<span class="row-here"> ← answer here</span>':''}</th><td>${active===activity?`<input id="answer" data-response inputmode="numeric" type="text" autocomplete="off" maxlength="30" value="${esc(value)}" aria-labelledby="question-title" aria-label="${activity} number of votes">`:`<span class="recorded-value">${esc(value||'—')}</span>${review?'<span class="review-label">Review</span>':''}`}</td></tr>`;}).join('')}</tbody></table><p class="template-note">${tr(active?'Tap slips to mark them while counting. Only the highlighted answer box is editable.':'These are your totals. Revisit a count slide if you want to correct one.','点投票纸可以做计数标记。只有高亮的答案框可以填写。')}</p></div>`;}
function schoolTable(caption,rows){return `<table class="scenario-table"><caption>${caption}</caption><thead><tr><th scope="col">${tr('Item / group','物品／类别')}</th><th scope="col">${tr('Total','总数')}</th></tr></thead><tbody>${rows.map(([name,value])=>`<tr><th scope="row">${name}</th><td>${value}</td></tr>`).join('')}</tbody></table>`;}
function lostTray(){const bottle='<svg width="28" height="39" viewBox="0 0 28 39" focusable="false"><rect x="9" y="1" width="10" height="5" rx="1" fill="#285c81"/><path d="M10 7h8v4l4 5v18q0 3-3 3H9q-3 0-3-3V16l4-5z" fill="#d7edf8" stroke="#356f97" stroke-width="2"/><path d="M8 23h12v11q0 1-1 1H9q-1 0-1-1z" fill="#75b9dc"/></svg>';return `<div class="scenario-heading">${tr('School office · eight lost items','学校办公室 · 八件失物')}</div><div class="lost-tray">${L.lostItems.map(([name,cn],i)=>`<button data-item="${i}" aria-pressed="${record().marks.includes(i)}" class="lost-item ${record().marks.includes(i)?'marked':''}"><span class="item-icon" aria-hidden="true">${name==='Water bottle'?bottle:{Cap:'🧢',Pencil:'✏️',Coat:'🧥',Scarf:'🧣',Jumper:'👕'}[name]}</span><span>${tr(esc(name),cn)}</span></button>`).join('')}</div><p class="visual-caption">${tr('Tap an item to mark it while counting.','点一下物品，可以做计数标记。')}</p>`;}
function arcadeHTML(){return `<div class="arcade-content"><p class="arcade-intro">${tr('You have finished the plenary. Choose a practice game and try five numbers. Check any mistakes, then try to improve. Stay with four bits today. Our BlastRoom class quiz is also saved here for when Mr Dave hosts it.','你已完成课堂总结。选择一个练习游戏，尝试五个数字。检查错误，再尝试进步。今天只练习四位二进制数。这里也保存了 BlastRoom 课堂测验，供 Dave 老师主持时使用。')}</p><div class="arcade-grid">${L.arcadeGames.map(g=>`<section class="arcade-card ${g.teacherHosted?'teacher-hosted':''}"><span class="arcade-symbol" aria-hidden="true">${g.symbol}</span><h2>${tr(g.title,g.zhTitle)}</h2><p class="arcade-name">${g.name}</p>${g.teacherHosted?`<p><strong>${tr('Teacher-hosted · room code needed','老师主持 · 需要房间代码')}</strong></p>`:''}<p>${tr(g.instruction,g.zhInstruction)}</p><a class="primary game-link" data-external-game="${g.id}" href="${g.url}" target="_blank" rel="noopener noreferrer">${tr(g.linkLabel||'Open game ↗',g.zhLinkLabel||'打开游戏 ↗')}</a>${g.joinUrl?`<a class="primary game-link" data-external-game="${g.id}" href="${g.joinUrl}" target="_blank" rel="noopener noreferrer">${tr('Join the class game ↗','加入课堂游戏 ↗')}</a>`:''}</section>`).join('')}</div><div class="arcade-fallback"><div><strong>${tr('Prefer our explorer game?','更喜欢我们的探险游戏？')}</strong><p>${tr('Binary Summit stays inside this app. No account or external website is needed.','Binary Summit 就在本应用内，不需要账号或其他网站。')}</p></div><button data-replay>Play Binary Summit ↑</button></div><p class="arcade-note">${tr('External links open in a new tab. Return here for your saved lesson. Do not sign up or enter your full name. For a teacher-hosted BlastRoom game, use only the nickname your teacher approves. We record opened links, not your answers or scores on another website. If a site is blocked or no class game is running, use Binary Summit or a practice game.','外部链接会在新标签页打开。回到这里即可查看已保存的课程。请勿注册或输入全名。参加老师主持的 BlastRoom 游戏时，只使用老师同意的昵称。本应用只记录打开的链接，不记录其他网站上的答案或分数。如果网站被拦截，或课堂游戏尚未开始，请玩 Binary Summit 或其他练习游戏。')}</p></div>`;}
function visual(s){const r=record();switch(s.visual){
 case 'hero':return image('explorer-welcome','An explorer robot welcomes you to a learning adventure.');
 case 'pattern':return `<div class="number-path"><span>1</span><b>→</b><span>2</span><b>→</b><span>4</span><b>→</b><span class="unknown-number ${r.check?'revealed':''}">${r.check?'8':'?'}</span></div><p class="visual-caption">${tr('Double each time','每次加倍')}</p>${r.check?'<p class="pattern-explanation">4 + 4 = 8</p>':''}`;
 case 'sum':return `<div class="dot-sum"><div>${'<i></i>'.repeat(4)}</div><b>+</b><div>${'<i></i>'.repeat(2)}</div></div><p class="big-equation">4 + 2 = ?</p>`;
 case 'sheet':return `<div class="sheet-frame"><span class="visual-caption">Spreadsheet starting-point check</span><table class="sheet"><thead><tr><th></th><th>A</th><th>B</th></tr></thead><tbody><tr><th>1</th><td>Activity</td><td>Votes</td></tr><tr><th>2</th><td>Chess</td><td>4</td></tr><tr><th>3</th><td>Football</td><td>2</td></tr></tbody></table><p class="visual-caption">Column letters · Row numbers</p></div>`;
 case 'learning':return `<div class="learning-visual">${image('reflection-camp','An explorer pauses to think about learning.')}<div class="learning-word">${{'type-knowledge':'Knowledge · Remember','type-skills':'Skills · Practise','type-understanding':'Understanding · Explain'}[s.id]}</div></div>`;
 case 'vote-story':return `${image('vote-story','A ballot box beside chess, football, drawing and reading materials.')}<p class="visual-caption">Eight votes. One results table. A useful answer.</p>`;
 case 'vote-template':return voteTemplate(s);
 case 'vote-repair':return `<div class="scenario-heading">${tr('Original votes','原始投票')}</div><div class="vote-slips">${L.votes.map(v=>`<span class="slip">${esc(v)}</span>`).join('')}</div>${schoolTable(tr('Office copy — check Football','办公室的抄录表：检查 Football'),[['Chess','4'],['<strong>Football</strong>','<strong class="mistaken-total">3 ?</strong>'],['Drawing','1'],['Reading','1']])}`;
 case 'lost-tray':return lostTray();
 case 'lost-results':return schoolTable(tr('Checked lost-property totals','已核对的失物总数'),[[tr('Bottles','水瓶'),'3'],[tr('Clothing','衣物'),'4'],[tr('Stationery','文具'),'1']]);
 case 'canteen':return `<div class="scenario-heading">${tr('Before the new orders','新增订单之前')}</div>${schoolTable(tr('Lunch orders','午餐订单'),[[tr('Sandwiches','三明治'),'5'],[tr('Pasta','意面'),'3'],[tr('Rice','米饭'),'2']])}<div class="new-orders">${tr('+ 2 new sandwich orders','＋ 2 份新增三明治订单')}</div>`;
 case 'canteen-results':return `${schoolTable(tr('Updated lunch orders · checked totals','更新后的午餐订单：已核对'),[[tr('Sandwiches','三明治'),'7'],[tr('Pasta','意面'),'3'],[tr('Rice','米饭'),'2']])}<p class="visual-caption">${tr('Sandwiches: 5 + 2 = 7','三明治：5 + 2 = 7')}</p>`;
 case 'labels':return `<div class="label-example"><div><small>Without a label</small><strong>4</strong></div><div><small>With a label</small><strong>Chess:<br>4 votes</strong></div></div>`;
 case 'bit':return `<div class="one-bit"><span class="visual-caption">${tr('One bit — tap to explore','一位：点一下试试')}</span><button data-demo-bit aria-label="One bit, currently ${state.demo?.tile||0}. Tap to switch.">${state.demo?.tile||0}</button><p>0 <span aria-hidden="true">↔</span> 1</p></div>`;
 case 'byte':return `<div class="byte-visual"><span class="visual-caption">${tr('Each box is one bit','每个方框是一位')}</span>${boxes('01010010')}<div class="byte-bracket">8 bits = 1 byte</div><p class="visual-caption">Count the boxes, including the zeroes.</p></div>`;
 case 'four':return `<div class="byte-visual">${boxes('0101')}<div class="four-label">4 boxes = 4 bits</div><p class="visual-caption">A byte needs eight bits.</p></div>`;
 case 'weights':return image('binary-power','The fixed values 8, 4, 2, 1, with exactly eight, four, two and one dots.');
 case 'zero-rule':return board('0000');
 case 'example':return `${board('0101')}<div class="example-total">4 + 1 = 5 <span>→ 0101</span></div>`;
 case 'binary':return board(answerBits(s),true,{live:!!s.live});
 case 'read10':return board('1010');
 case 'read-pattern':return board(s.digits,false,{live:!!r.check});
 case 'camp':return image('reflection-camp','A robot takes a calm learning pitstop with a notebook.');
 default:return '';
}}
function responseHTML(s){const r=record();
 if(s.kind==='arcade')return '';
 if(s.kind==='vote')return `<p class="answer-direction">${tr(`Type your total in the highlighted ${s.activity} box.`,`把总数填入高亮的 ${s.activity} 答案框。`)}</p>`;
 if(s.kind==='binary')return `<p class="answer-direction">${tr('Tap the cards on the left. Your four digits are one answer.','点左边的卡片。四个数字组成一个答案。')}</p><output class="answer-code" aria-label="Your four-bit answer">${answerBits(s)}</output>`;
 if(s.kind==='number')return `<div class="number-answer"><input id="answer" data-response type="text" inputmode="numeric" autocomplete="off" maxlength="30" aria-labelledby="question-title" value="${esc(r.answer==='not-yet'?'':r.answer)}" placeholder="Your number"></div>`;
 const opts=s.kind==='confidence'?(s.confidenceOptions||L.confidence):s.kind==='phase'?L.phases:s.options;
 return `<div class="answer-options ${s.kind==='phase'?'phase-options':''}" role="group" aria-labelledby="question-title">${opts.map(([value,label,detail,cn],i)=>`<button data-choice="${value}" class="answer-option" aria-pressed="${r.answer===value}"><span class="option-letter" aria-hidden="true">${String.fromCharCode(65+i)}</span><span>${esc(label)}${s.kind==='phase'?`<small>${esc(detail)}</small>`:''}${state.lang==='zh'&&(s.kind==='confidence'||s.kind==='phase'||detail)?`<span class="zh" lang="zh-Hans">${esc(s.kind==='phase'?cn:detail)}</span>`:''}</span></button>`).join('')}</div>`;
}
function explanationZH(s){const map={welcome:'停止操作并看屏幕。需要帮助时，留在座位上举手。','starter-pattern':'下一个数字是 8。每次加倍：1 → 2 → 4 → 8。','starter-add':'四个圆点加两个圆点，一共六个。4 + 2 = 6。','starter-cell':'B2 在 B 列第 2 行，里面是数字 4。','task1-data':'是的。数据可以是文字，也可以是数字。投票纸记录了同学的选择。','task1-information':'Chess 有八票中的四票，比其他活动多。这帮助老师选择活动。','task1-labels':'“Chess: 4 votes”说明了活动名称，以及数字表示的票数。',bit:'一位只能是 0 或 1。改变数值后，它仍然只是一位。',byte:'一个字节包含八个位。0 也是一位，要数全部方框。','four-bits':'四个位不是一个字节。一个字节需要八个位。',positions:'从左到右是 8、4、2、1，所以第二列的位值是 4。','count-rule':'不计入 8。位值仍是 8，但下面的数字 0 表示不把它加入总数。',example:'4 + 1 = 5，所以四位二进制数是 0101。',guided:'计入 4 和 2：4 + 2 = 6，四位数字是 0110。',make3:'2 + 1 = 3，所以四位数字是 0011。',make9:'8 + 1 = 9，所以四位数字是 1001。',read10:'1010 计入 8 和 2：8 + 2 = 10。','exit-info':'完整的说法说明了活动及结果。只有数字 4，没有足够的含义。','exit-binary':'6 = 4 + 2，所以四位数字是 0110。','exit-byte':'一个字节有八个位。我们练习的四个位不是一个完整的字节。'};return s.kind==='vote'?`${s.activity} 有 ${s.correct} 票。原来的答案会保留，你也可以修改后再继续。`:map[s.id]||'';}
function feedback(){const c=record().check;return c?`<div class="feedback ${c.correct===true?'correct':c.correct===false?'review':'neutral'}" role="status"><strong>${c.correct===true?'That is correct.':c.correct===false?'Not yet — review this explanation.':'Your choice is recorded.'}</strong><p>${tr(esc(c.message),current().zhExplain||explanationZH(current()))}</p>${c.correct===false?'<small>You can change your answer or use Next. You are not stuck here.</small>':''}</div>`:'';}
function render(){
 const s=current(),r=record(),section=slides.filter(p=>p.stage===s.stage),n=section.indexOf(s),core=slides.filter(p=>!['game','finish','arcade'].includes(p.kind)),complete=core.filter(p=>state.done.includes(p.id)).length;
 $('#app').innerHTML=`<div class="lesson-screen"><header class="app-header"><div class="brand"><img src="assets/explorer-sprite.png" alt=""><strong>Binary Explorer</strong><span class="pupil-name">${esc(state.identity.name)} · ${esc(state.identity.cls)}</span></div><div class="app-tools"><span class="save-status">Saved on this device</span><button data-backup>↓ Backup</button><select data-lang aria-label="Language support"><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="zh" ${state.lang==='zh'?'selected':''}>English + 中文</option></select><button data-help="words">Words / 词汇</button><button data-help="device">Device help</button><button data-leave>Leave</button></div></header><section class="learning-strip" aria-label="Persistent learning information"><p><strong>WAGBA:</strong> ${L.wagba}</p><div class="ksu"><span><strong>Knowledge:</strong> bit = 0 or 1; byte = 8 bits.</span><span><strong>Skills:</strong> organise votes; make and read binary.</span><span><strong>Understanding:</strong> labels and position give meaning.</span></div><p class="keyword-line"><strong>Keywords:</strong> data · information · bit · byte · binary · place value</p></section><nav class="lesson-journey" aria-label="Lesson sections">${L.stages.map(([label],i)=>{const group=slides.filter(p=>p.stage===i),done=group.every(p=>state.done.includes(p.id)),open=teacher()||slides.indexOf(group[0])<=state.furthest;return `<button data-section="${i}" ${s.stage===i?'aria-current="step"':''} class="${done?'completed':''} ${open?'':'unreached'}" aria-label="${label}${done?', completed':open?'':', not reached yet'}"><span>${done?'✓':i+1}</span>${label}</button>`;}).join('')}</nav><div class="progress-line"><span>${L.stages[s.stage][0]} · Slide ${n+1} of ${section.length}</span><div class="progress-track" role="progressbar" aria-label="Lesson completion" aria-valuemin="0" aria-valuemax="${core.length}" aria-valuenow="${complete}"><i style="width:${complete/core.length*100}%"></i></div><span>${complete}/${core.length} completed</span></div><main id="main" class="lesson-main"><article class="slide ${s.kind==='game'?'game-slide':''} ${s.kind==='finish'?'finish-slide':''}" tabindex="-1"><div class="slide-title"><span class="eyebrow">${L.stages[s.stage][1]} · ${L.stages[s.stage][2]}</span><h1>${s.title}</h1></div>${s.kind==='game'?gameHTML():s.kind==='finish'?finishHTML():`<div class="slide-body"><div class="slide-visual">${visual(s)}</div><div class="slide-learning"><div class="reading"><span class="reading-label">READ FIRST</span><p>${tr(esc(s.lead),s.zhLead)}</p></div><section class="one-question" aria-labelledby="question-title"><span class="question-label">${['confidence','phase','reflection'].includes(s.kind)?'YOUR REFLECTION':'YOUR QUESTION'}</span><h2 id="question-title">${tr(esc(s.prompt),s.zhPrompt)}</h2>${responseHTML(s)}</section>${s.hint?`<button class="hint-button" data-hint>Show a hint</button>${r.hint?`<div class="hint">${esc(s.hint)}</div>`:''}`:''}<div id="feedback">${feedback()}</div><div id="answer-notice" role="status"></div></div></div>`}</article></main><footer class="slide-footer"><button data-back ${state.p===0?'disabled':''}>← Back</button><span class="footer-status">${s.kind==='game'?'Extra challenge — you may continue to Pitstop anytime.':s.kind==='finish'?'Your work is saved on this device.':r.check?'Answer reviewed · You can continue.':'One question · One response'}</span>${s.kind==='finish'?'<button class="primary" data-backup>Download backup</button>':`<button class="primary" data-primary>${s.kind==='game'?'Continue to Pitstop →':teacher()&&!r.check&&!r.answer.trim()?'Next slide →':r.check?(s.nextLabel||'Next slide →'):['confidence','phase','reflection'].includes(s.kind)?'Save choice and continue →':'Check answer'}</button>`}</footer></div><input id="restore-file" type="file" accept=".json,application/json" hidden>`;
 if(current().kind==='confidence'||(current().options&&current().options.length>=3))$('.answer-options')?.classList.add('compact-options');
 $('.ksu span:nth-child(2)').innerHTML='<strong>Skills:</strong> organise school data; make and read binary.';
 if(['confidence','phase','reflection'].includes(current().kind)){
   $('.slide-body').classList.add('reflection-layout');
   $('.slide-visual').prepend($('.reading'));
 }
 if(s.id==='type-knowledge'){
   $('.slide').classList.add('knowledge-slide');
   $('.slide-title').insertAdjacentHTML('afterend',`<aside class="learning-definition" aria-labelledby="learning-definition-heading"><h2 id="learning-definition-heading">${tr('Definition of learning','学习的定义')}</h2><p>${tr(esc(s.learningDefinition),s.zhLearningDefinition)}</p></aside>`);
   $('.slide-visual').innerHTML=`<section class="today-knowledge" aria-labelledby="today-knowledge-heading"><span class="reading-label">${tr('TODAY’S COMPUTING KNOWLEDGE','今天的计算机知识')}</span><h2 id="today-knowledge-heading">${tr('Two facts to remember','记住这两条知识')}</h2><ol>${s.knowledgeFacts.map(([en,zh])=>`<li>${tr(esc(en),zh)}</li>`).join('')}</ol></section>`;
 }
 if(s.hint&&record().hint&&state.lang==='zh'&&s.zhHint)$('.hint')?.insertAdjacentHTML('beforeend',tr('',s.zhHint));
 if(s.kind==='arcade'){
   $('.slide').classList.add('arcade-slide');$('.slide-body').outerHTML=arcadeHTML();
   $('[data-primary]').textContent='Review my work →';$('.footer-status').textContent='Extra practice · Choose a game or review your work';
 }
 if(s.kind==='game'&&state.arcadeReturn){$('[data-primary]').textContent='Return to Binary Arcade →';$('.footer-status').textContent='Extra practice · Return anytime';}
 // Show feedback-corrected reference totals without deleting the student's original response.
 if($('.vote-table'))$$('.vote-table tbody tr').forEach((row,i)=>{
   const activity=L.activities[i],id='vote-'+activity.toLowerCase(),entry=state.records[id];
   if(entry?.check?.correct===false&&!(current().kind==='vote'&&current().activity===activity)){
     const correct=slides.find(s=>s.id===id).correct;
     row.querySelector('td').innerHTML=`<strong class="checked-total">${correct}</strong><span class="review-label">Your entry: ${esc(entry.answer)} · corrected after feedback</span>`;
   }
 });
 if($('.template-note')&&current().kind!=='vote')$('.template-note').innerHTML=tr('These are your recorded totals. Revisit a count slide if you want to correct one.','这些是你记录的票数。需要修改时，可以返回对应的数票页面。');
 ensureCheckButton();bind();save();
}
function setAnswer(answer){const r=record();r.answer=answer;r.check=null;state.done=state.done.filter(id=>id!==current().id);save();}
function ensureCheckButton(){
 const s=current(),q=$('.one-question');
 if(!q||['confidence','phase','reflection'].includes(s.kind))return;
 if(record().check){$('[data-check-answer]')?.remove();return;}
 if(!$('[data-check-answer]'))q.insertAdjacentHTML('beforeend','<div class="answer-actions"><button class="primary" data-check-answer>Check answer</button></div>');
 $('[data-check-answer]').onclick=checkCurrent;
}
function updateAnswerUI(){const s=current(),r=record();$$('[data-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.choice===r.answer)));$('#feedback')?.replaceChildren();$('#answer-notice')?.replaceChildren();$('.one-question')?.classList.remove('needs-answer');const b=$('[data-primary]');if(b)b.textContent=teacher()&&!r.answer.trim()?'Next slide →':['confidence','phase','reflection'].includes(s.kind)?'Save choice and continue →':'Check answer';ensureCheckButton();}
function bind(){
 $$('[data-response]').forEach(e=>{e.oninput=()=>{setAnswer(e.value);updateAnswerUI();};e.onchange=()=>{log('response',record().answer);save();};e.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();checkCurrent();}};});
 $$('[data-choice]').forEach(b=>b.onclick=()=>{setAnswer(b.dataset.choice);log('choice',b.dataset.choice);updateAnswerUI();save();});
 $$('[data-slip]').forEach(b=>b.onclick=()=>{const r=record(),i=Number(b.dataset.slip);r.marks=r.marks.includes(i)?r.marks.filter(x=>x!==i):[...r.marks,i];b.classList.toggle('marked',r.marks.includes(i));b.setAttribute('aria-pressed',String(r.marks.includes(i)));log('counting-mark',{slip:i,marked:r.marks.includes(i)});save();});
 $$('[data-item]').forEach(b=>b.onclick=()=>{const r=record(),i=Number(b.dataset.item);r.marks=r.marks.includes(i)?r.marks.filter(x=>x!==i):[...r.marks,i];b.classList.toggle('marked',r.marks.includes(i));b.setAttribute('aria-pressed',String(r.marks.includes(i)));log('item-mark',{item:i,marked:r.marks.includes(i)});save();});
 $$('[data-external-game]').forEach(a=>a.addEventListener('click',()=>{log('external-game-open',{id:a.dataset.externalGame,url:a.href});save();}));
 $('[data-replay]')?.addEventListener('click',()=>{state.arcadeReturn=true;log('arcade-replay','summit');go(slides.findIndex(s=>s.id==='summit'));});
 $$('[data-bit]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.bit),game=b.dataset.game==='true';if(game){if(state.game.charged)return;state.game.bits[i]^=1;state.game.feedback=null;}else{const d=answerBits(current()).split('');d[i]=d[i]==='1'?'0':'1';setAnswer(d.join(''));}log('binary-card',{game,column:weights[i]});save();render();$(`[data-bit="${i}"]`)?.focus({preventScroll:true});});
 $('[data-demo-bit]')?.addEventListener('click',()=>{state.demo.tile=state.demo.tile?0:1;$('[data-demo-bit]').textContent=state.demo.tile;$('[data-demo-bit]').setAttribute('aria-label',`One bit, currently ${state.demo.tile}. Tap to switch.`);log('one-bit-demo',state.demo.tile);save();});
 $('[data-hint]')?.addEventListener('click',()=>{record().hint=true;log('hint',current().hint);save();render();const hint=$('.hint');if(hint){hint.setAttribute('tabindex','-1');hint.focus({preventScroll:true});hint.scrollIntoView({block:'nearest',behavior:'smooth'});}});
 $('[data-primary]')?.addEventListener('click',primaryAction);
 $('[data-back]').onclick=()=>go(state.p-1);
 $$('[data-section]').forEach(b=>b.onclick=()=>{const group=slides.filter(s=>s.stage===Number(b.dataset.section)),start=slides.indexOf(group[0]);if(!teacher()&&start>state.furthest){toast('Try the one question here and use Check answer, then Next. Incorrect answers do not block you.');return;}const first=group.find(s=>!state.done.includes(s.id))||group[0];go(Math.min(slides.indexOf(first),teacher()?slides.length-1:state.furthest));});
 $$('[data-backup]').forEach(b=>b.onclick=backup);
 $('[data-lang]').onchange=e=>{state.lang=e.target.value;log('language',state.lang);save();render();};
 $$('[data-help]').forEach(b=>b.onclick=()=>help(b.dataset.help));
 $('[data-leave]').onclick=()=>{save();landing();};
 $('#restore-file').onchange=e=>restore(e.target.files[0]);
 $$('[data-review]').forEach(b=>b.onclick=()=>go(slides.findIndex(s=>s.id===b.dataset.review)));
 $('[data-print]')?.addEventListener('click',printReport);
 $('[data-restore]')?.addEventListener('click',()=>$('#restore-file').click());
 $('[data-game-check]')?.addEventListener('click',gameCheck);
 $('[data-game-hint]')?.addEventListener('click',()=>{state.game.hint=true;log('game-hint',gameQuestion());save();render();});
 $('[data-game-answer]')?.addEventListener('input',e=>{state.game.answer=e.target.value;state.game.feedback=null;save();});
 $('[data-jump]')?.addEventListener('click',jump);
 $('[data-new-climb]')?.addEventListener('click',()=>{const old=state.game;state.game={...freshGame(),climb:old.climb+1,attempts:old.attempts,completed:old.completed};log('new-climb',state.game.climb);save();render();});
}
function evaluate(s,a){if(['confidence','phase','reflection'].includes(s.kind))return {correct:null,message:'Your reflection is recorded. Use it to choose the help or challenge you need.'};if(s.diagnostic&&a==='not-yet')return {correct:null,message:'It is fine if this is new. '+s.explain};const clean=x=>String(x).replace(/\s/g,'').toLowerCase();return {correct:clean(a)===clean(s.correct),message:s.explain};}
function primaryAction(){const s=current(),r=record();if(s.kind==='arcade'){if(!state.done.includes(s.id))state.done.push(s.id);log('arcade-reviewed','Game play is extra practice, not a submission requirement.');go(state.p+1);return;}if(s.kind==='game'){if(state.game.attempts.length&&!state.done.includes(s.id))state.done.push(s.id);if(state.arcadeReturn){state.arcadeReturn=false;go(slides.findIndex(s=>s.id==='arcade'));}else go(state.p+1);return;}if(teacher()&&!r.check&&!r.answer.trim()){go(state.p+1);return;}if(r.check){if(!state.done.includes(s.id))state.done.push(s.id);log('completed',{correct:r.check.correct});go(state.p+1);return;}checkCurrent();}
function checkCurrent(){const s=current(),r=record(),a=s.kind==='binary'?(r.answer||s.initial):r.answer.trim();if(!a){$('.one-question').classList.add('needs-answer');$('#answer-notice').innerHTML='<p class="answer-alert">Try this one question first. Choose an answer or type in the highlighted answer box.</p>';($('#answer')||$('[data-choice]'))?.focus({preventScroll:true});return;}r.answer=a;r.check={...evaluate(s,a),at:new Date().toISOString()};log('checked',{answer:a,...r.check});save();if(['confidence','phase','reflection'].includes(s.kind)){state.done.push(s.id);go(state.p+1);}else{render();const box=$('.feedback');if(box){box.setAttribute('tabindex','-1');box.focus({preventScroll:true});box.scrollIntoView({block:'nearest',behavior:'smooth'});}}}
function go(i){if(i<0||i>=slides.length)return;if(slides[i].kind!=='game')state.arcadeReturn=false;state.p=i;state.furthest=Math.max(state.furthest,i);log('navigation',current().id);save();render();$('.lesson-main')?.scrollTo(0,0);$('.slide')?.focus({preventScroll:true});window.scrollTo(0,0);}
function gameQuestion(){const g=state.game,targets=[5,9,6,10,5,7];return {type:g.index<2?'make':g.index<4?'read':'repair',target:g.climb===1?targets[g.index]:(targets[g.index]+(g.climb-1)*3)%16};}
function gameHTML(){const g=state.game,q=gameQuestion(),finished=g.height===6,pos=stops[g.height];return `<div class="slide-body game-body"><div class="game-world"><div class="mountain"><img src="assets/summit-mountain.png" class="mountain-art" alt="A colourful mountain path with a flag at the summit.">${stops.map(([x,y])=>`<i class="platform" style="left:${x}%;top:${y}%"></i>`).join('')}<img class="game-character ${state.color}" src="assets/explorer-sprite.png" style="left:${pos[0]}%;top:${pos[1]}%" alt="Your explorer has completed ${g.height} of six jumps."><span class="mountain-status">${g.height}/6 jumps · Climb ${g.climb}</span></div><p class="game-mission">${tr('Solve one puzzle. Charge one jump. Tap to climb.','解答一道题，充能一次，再点按钮向上跳。')}</p><p class="visual-caption">No lost lives or countdown. Energy is a game reward, not a bit or byte.</p></div><div class="slide-learning">${finished?`<div class="summit-finish"><span>⚑</span><h2>Summit reached!</h2><p>You solved six puzzles. Start another climb or continue to Learning Pitstop.</p><button class="primary" data-new-climb>Start another climb</button></div>`:`<span class="eyebrow">Puzzle ${g.index+1} of 6 · ${q.type==='read'?'Read a signal':q.type==='make'?'Make a number':'Repair a signal'}</span><h2 class="game-prompt">${q.type==='read'?`What number is ${bits(q.target)}?`:`Make ${q.target}.`}</h2><p>${tr(q.type==='read'?'Add the values under the 1 digits.':'Tap the cards you need, then check your answer.',q.type==='read'?'把数字 1 所在列的位值相加。':'点选需要的卡片，再检查答案。')}</p>${q.type==='read'?board(bits(q.target)):board(g.bits.join(''),true,{live:g.index<2,game:true})}${q.type==='read'?`<input data-game-answer aria-label="Your ordinary number" inputmode="numeric" value="${esc(g.answer)}" placeholder="Your number">`:''}<div class="game-actions">${g.charged?'<button class="primary" data-jump>Jump to the next platform ↑</button>':'<button class="primary" data-game-check>Check and charge my jump</button>'}<button class="hint-button" data-game-hint>Hint</button></div>${g.hint?`<div class="hint">${q.type==='read'?'Add the values under the 1s. Ignore the columns with 0.':`Start with the biggest value that fits ${q.target}. Work out how much is left.`}</div>`:''}${g.feedback?`<div class="feedback ${g.feedback.correct?'correct':'review'}" role="status">${esc(g.feedback.message)}</div>`:''}`}</div></div>`;}
function gameCheck(){const g=state.game;if(g.charged||g.height===6)return;const q=gameQuestion();if(q.type==='read'&&!g.answer.trim()){g.feedback={correct:false,message:'Type the number you think the signal represents, then check.'};render();return;}const value=q.type==='read'?Number(g.answer):sum(g.bits.join('')),correct=value===q.target,attempt={at:new Date().toISOString(),climb:g.climb,puzzle:g.index+1,type:q.type,target:q.target,response:q.type==='read'?g.answer:g.bits.join(''),correct,hint:g.hint};g.attempts.push(attempt);log('game-attempt',attempt);const counted=(q.type==='read'?bits(q.target):g.bits.join('')).split('').map((b,i)=>b==='1'?weights[i]:null).filter(x=>x!==null).join(' + ')||'No values counted';g.charged=correct;g.feedback={correct,message:correct?`Correct! ${counted} = ${q.target}. Your jump is ready.`:`Not yet. ${q.type==='read'?'Add the column values under the 1s again.':`Your cards make ${value}; your target is ${q.target}.`} Try again or use Hint. You may also continue to Pitstop.`};save();render();}
function jump(){const g=state.game;if(!g.charged||g.height===6)return;g.height++;g.index++;g.charged=false;g.hint=false;g.feedback=null;g.answer='';g.bits=g.index>=4?[0,1,0,0]:[0,0,0,0];if(g.height===6)g.completed++;log('jump',{climb:g.climb,height:g.height});save();const img=$('.game-character'),b=$('[data-jump]');if(img){img.style.left=stops[g.height][0]+'%';img.style.top=stops[g.height][1]+'%';}if(b){b.disabled=true;b.textContent='Climbing…';}setTimeout(()=>{if(state&&current().kind==='game'&&state.game===g)render();},matchMedia('(prefers-reduced-motion: reduce)').matches?0:850);}
function answerLabel(s,a){if(!a)return 'Not answered';if(a==='not-yet')return 'Not learned yet';const opts=s.kind==='confidence'?(s.confidenceOptions||L.confidence):s.kind==='phase'?L.phases:s.options;return opts?.find(o=>o[0]===a)?.[1]||(s.kind==='confidence'?L.confidence.find(o=>o[0]===a)?.[1]:null)||a;}
function finishHTML(){
 const attempted=slides.filter(s=>state.records[s.id]?.check),correct=attempted.filter(s=>state.records[s.id].check.correct===true),opened=state.history.filter(e=>e?.type==='external-game-open'&&typeof e.value?.id==='string'&&typeof e.at==='string');
 return `<div class="finish-intro"><div>${image('reflection-camp','Your explorer reviews the learning journey.')}</div><div><h2>Your work is ready to review.</h2><p>${attempted.length} responses recorded · ${correct.length} latest checks correct · ${state.game.completed} summits reached.</p><p>Keep a backup before changing device. There is no automatic teacher upload and no screenshot task.</p><div class="finish-actions"><button class="primary" data-backup>Download JSON backup</button><button data-print>Print / save PDF backup</button><button data-restore>Restore backup</button></div></div></div><div class="review-sections">${L.stages.map(([label],i)=>{const group=slides.filter(s=>s.stage===i&&!['game','finish','arcade'].includes(s.kind));return group.length?`<details><summary>${label} · ${group.filter(s=>state.records[s.id]?.check).length}/${group.length} responses</summary>${group.map(s=>`<div class="review-row"><div><strong>${s.title}</strong><span>${esc(answerLabel(s,state.records[s.id]?.answer))}</span></div><button data-review="${s.id}">Review slide</button></div>`).join('')}</details>`:'';}).join('')}<details><summary>Binary Arcade · ${opened.length} link openings</summary><p class="arcade-note">External answers and scores are not tracked. Game play is extra practice.</p>${opened.map(e=>`<div class="review-row">${esc(L.arcadeGames.find(g=>g.id===e.value.id)?.name||e.value.id)} · ${esc(new Date(e.at).toLocaleTimeString())}</div>`).join('')}<button data-review="arcade">Return to Binary Arcade</button></details></div>`;
}
function filename(){return ['Year7',state.identity.cls,state.identity.name,'Data_Binary'].map(x=>x.replace(/[^\p{L}\p{N}_-]+/gu,'_')).filter(Boolean).join('_');}
function backup(){log('backup','JSON');save();const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=filename()+'.json';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);toast('Backup created. If a preview opens on iPad, use Share → Save to Files.');}
async function restore(file){if(!file)return;try{if(file.size>4_000_000)throw Error('Too large');const raw=JSON.parse(await file.text()),next=normaliseSaved(raw)||migrate(raw);if(!next)throw Error('Invalid backup');if(state&&!confirm('Replace the current work on this device with this backup?'))return;state=next;storageKey=key(state.identity.name,state.identity.cls);if(!state.demo)state.demo={tile:0};save();render();toast('Your backup is restored.');}catch{toast('This is not a valid Binary Explorer backup. Your existing work has not changed.');}}
function printReport(){
 let report=$('.print-report');if(!report){report=document.createElement('section');report.className='print-report';document.body.append(report);}
 const opened=state.history.filter(e=>e?.type==='external-game-open'&&typeof e.value?.id==='string'&&typeof e.at==='string');
 report.innerHTML=`<h1>Year 7 · Data and four-bit binary</h1><p><strong>${esc(state.identity.name)} · ${esc(state.identity.cls)}</strong></p><p><strong>WAGBA:</strong> ${L.wagba}</p>${slides.filter(s=>state.records[s.id]?.answer).map(s=>{const r=state.records[s.id];return `<section class="report-question"><h2>${s.title}</h2><p>${esc(s.prompt)}</p><p><strong>Response:</strong> ${esc(answerLabel(s,r.answer))}</p>${r.check?`<p><strong>${r.check.correct===true?'Correct':r.check.correct===false?'Review needed':'Reflection recorded'}:</strong> ${esc(r.check.message)}</p>`:''}</section>`;}).join('')}<section class="report-question"><h2>Binary Summit</h2><p>${state.game.completed} summits reached.</p>${state.game.attempts.map(a=>`<p>Climb ${a.climb}, puzzle ${a.puzzle}: target ${a.target}; answer ${esc(a.response)}; ${a.correct?'correct':'retry'}${a.hint?'; hint used':''}.</p>`).join('')}</section><section class="report-question"><h2>Binary Arcade</h2><p>External game links opened: ${opened.length}. These are link openings, not evidence of external game completion. External answers and scores are not tracked.</p>${opened.map(e=>`<p>${esc(L.arcadeGames.find(g=>g.id===e.value.id)?.name||e.value.id)} · ${esc(new Date(e.at).toLocaleString())}</p>`).join('')}</section>`;
 log('backup','Print/PDF');save();window.print();
}
function help(type){const words=[['data','数据','Recorded facts or choices. Words can be data.'],['information','信息','What data tells us when we organise and interpret it.'],['bit','位（比特）','One binary digit: 0 or 1.'],['byte','字节','Eight bits.'],['binary','二进制','A number system using the digits 0 and 1.'],['place value','位值','The value of a digit’s position.'],['cell','单元格','One box in a spreadsheet.'],['row','行','A row goes across.'],['column','列','A column goes up and down.']];$('#help-content').innerHTML=type==='words'?`<h2>Words / 词汇</h2><p>You may think or make notes in English, Mandarin or both. Keep the English computing words beside their translations.</p><table class="glossary">${words.map(([en,cn,d])=>`<tr><th>${en}<span lang="zh-Hans">${cn}</span></th><td>${d}</td></tr>`).join('')}</table><p>English + 中文 adds support to the teaching, questions and reflection choices. It is not a full translation of every interface control.</p>`:`<h2>Device help</h2><h3>One slide at a time</h3><p>Read the information, try the one question, then press <strong>Check answer</strong>. Read the explanation and use <strong>Next slide</strong>. Incorrect answers do not block you. For reflection slides, choose one response and press <strong>Save choice and continue</strong>.</p><h3>The vote template</h3><p>The same eight voting slips and table stay together. Only one row is editable at a time. Previous entries remain visible. This is an interactive lesson table, not Excel or Google Sheets. No screenshot is required.</p><h3>Saving on an iPad</h3><p>Tap <strong>Backup</strong> at the top. If Safari shows a preview, use <strong>Share → Save to Files</strong>. Choose a folder you can find again. A browser cannot guarantee an automatic save to a specific folder.</p><h3>Restore or change device</h3><p>Use Restore on the entry or Finish screen and choose your JSON backup. Work is stored in this browser only; changing device, browser or website address does not transfer it automatically.</p><h3>PDF and Teams</h3><p>Finish offers Print / save PDF as a backup. If your teacher requests a file, save it first, then open the Teams assignment, attach the file and hand it in. This lesson does not submit to Teams automatically.</p>`;$('#help').showModal();}
$('#close-help').onclick=()=>$('#help').close();
document.addEventListener('keydown',e=>{if(state&&e.key==='ArrowRight'&&!$('#help').open&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)&&record().check){e.preventDefault();primaryAction();}if(state&&current().kind==='game'&&e.code==='Space'&&state.game.charged&&!$('#help').open&&!['INPUT','SELECT','TEXTAREA','BUTTON'].includes(document.activeElement.tagName)){e.preventDefault();jump();}});
window.addEventListener('pagehide',save);
window.BinaryExplorer={getState:()=>structuredClone(state),slides:structuredClone(slides),evaluate,validState:valid,migrate,normaliseSaved};
try{landing();}catch(e){$('#app').innerHTML='<main class="startup-error"><h1>The lesson could not start.</h1><p>Reload the page. Check that lesson.js, app-v2.js, slide-styles.css and assets are beside index.html.</p></main>';console.error(e);}
})();
